<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/doctor_online_v580.php';$me=current_user();$aud=in_array((string)($_GET['audience']??'patient'),['patient','doctor','organization'],true)?(string)($_GET['audience']??'patient'):'patient';$plans=do580_plans($aud);$flash='';$error='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{$me=$me?:require_login();csrf_check();$planId=(int)($_POST['plan_id']??0);$q=db()->prepare('SELECT * FROM health_subscription_plans_v580 WHERE id=? AND tenant_id IN (0,?) AND status=1 LIMIT 1');$q->execute([$planId,do580_tid()]);$p=$q->fetch();if(!$p)throw new RuntimeException('Subscription plan not found.');$aud=(string)$p['audience'];$uid=null;$did=null;$oid=null;if($aud==='patient')$uid=(int)$me['id'];elseif($aud==='doctor'){$d=do580_doctor_by_user((int)$me['id']);if(!$d||$d['approval_status']!=='approved')throw new RuntimeException('An approved Doctor Online profile is required for a doctor plan.');$did=(int)$d['id'];$uid=(int)$me['id'];}else{$q=db()->prepare('SELECT id FROM health_organizations_v580 WHERE tenant_id=? AND owner_user_id=? AND status IN (\'active\',\'pending\') ORDER BY id LIMIT 1');$q->execute([do580_tid(),(int)$me['id']]);$oid=(int)$q->fetchColumn();if(!$oid)throw new RuntimeException('You do not own a healthcare organization in this tenant.');$uid=(int)$me['id'];}$method=(string)($_POST['payment_method']??'manual');$payment='pending';$status='pending';$start=null;$end=null;$credits=(int)$p['consultation_credits'];$q=db()->prepare('INSERT INTO health_subscriptions_v580(tenant_id,plan_id,audience,user_id,doctor_id,organization_id,amount,payment_method,payment_status,starts_at,ends_at,remaining_consults,status,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$q->execute([do580_tid(),$planId,$aud,$uid,$did,$oid,(float)$p['price'],$method,$payment,$start,$end,$credits,$status,'Public subscription request']);$sid=(int)db()->lastInsertId();if($method==='online_payment'&&function_exists('create_payment_order')&&(float)$p['price']>0){try{$pid=create_payment_order((int)$me['id'],(float)$p['price'],'doctor_online_subscription',null,null,null,'none',['health_subscription_id'=>$sid]);db()->prepare('UPDATE health_subscriptions_v580 SET payment_order_id=? WHERE id=?')->execute([$pid,$sid]);}catch(Throwable $e){}}$flash='Subscription request created. It becomes active after payment/approval according to platform settings.';do580_track('subscription_requested','subscription',$sid,['audience'=>$aud]);}catch(Throwable $e){$error=$e->getMessage();}}do580_public_header('Healthcare Plans','Patient, doctor and healthcare organization subscription plans.');
