<section class="do580-pagehead"><div class="do580-shell"><h1>Doctor Online subscriptions</h1><p>Patient consultation credits, doctor portal plans and hospital/clinic subscriptions. Admin can also assign or waive fees manually.</p></div></section><main class="do580-shell" style="padding:28px 0 56px"><div style="display:flex;gap:9px;margin-bottom:22px"><a class="do580-btn <?=$aud==='patient'?'primary':'secondary'?>" href="?audience=patient">Patient Plans</a><a class="do580-btn <?=$aud==='doctor'?'primary':'secondary'?>" href="?audience=doctor">Doctor Plans</a><a class="do580-btn <?=$aud==='organization'?'primary':'secondary'?>" href="?audience=organization">Hospital / Clinic</a></div><?php if($flash):?><div class="do580-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="do580-alert err"><?=e($error)?></div><?php endif;?><div class="do580-plan-grid"><?php foreach($plans as $i=>$p):$features=do580_decode($p['features_json']);?><article class="do580-plan <?=$i===1?'featured':''?>"><span class="do580-badge"><?=e(strtoupper($p['audience']))?></span><h3><?=e($p['name'])?></h3><p><?=e($p['description'])?></p><div class="price"><?=do580_money((float)$p['price'])?><small> / <?=max(1,(int)$p['duration_days'])?> days</small></div><?php if((int)$p['consultation_credits']>0):?><p><b><?=(int)$p['consultation_credits']?> consultation credit<?=((int)$p['consultation_credits']===1?'':'s')?></b></p><?php endif;?><ul><?php foreach($features as $x):?><li><?=e((string)$x)?></li><?php endforeach;?></ul><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="plan_id" value="<?=(int)$p['id']?>"><label style="font-size:12px">Payment<select name="payment_method"><?php if(function_exists('create_payment_order')):?><option value="online_payment">Online payment</option><?php endif;?><option value="manual">Manual / admin confirmation</option></select></label><button class="do580-btn primary" style="width:100%">Subscribe</button></form></article><?php endforeach;?><?php if(!$plans):?><div class="do580-panel">No active plans for this audience.</div><?php endif;?></div><div class="do580-clinical-note">Subscriptions manage platform access and consultation credits; they do not guarantee medical outcomes or replace emergency care.</div></main><?php do580_public_footer(); ?>
